local config = {
  str_homestory_N19chuanshanjia_90010101_1_dialog_content = "Cloud Gardens has been pretty lively lately.",
  str_homestory_N19chuanshanjia_90010101_2_dialog_content = "Right? It looks like there are a lot more animals here than before.",
  str_homestory_N19chuanshanjia_90010101_3_dialog_content = "But you know, I'm still curious about that scaly-armored creature everyone keeps talking about. What was it called again?",
  str_homestory_N19chuanshanjia_90010101_4_dialog_content = "The <color=#FFB400>Lithic Pangalo</color>?",
  str_homestory_N19chuanshanjia_90010101_5_dialog_content = "Yes!",
  str_homestory_N19chuanshanjia_90010101_6_dialog_content = "They're apparently able to burrow through the mountains and the ground with ease. It's pretty fascinating.",
  str_homestory_N19chuanshanjia_90010101_7_dialog_content = "What's that sound?",
  str_homestory_N19chuanshanjia_90010101_8_dialog_content = "That way!",
  str_homestory_N19chuanshanjia_90010101_9_dialog_content = "Covered head to toe in scales, with an enormous tail... Could that be a Pangalo right in front of us?!",
  str_homestory_N19chuanshanjia_90010101_10_dialog_content = "Hello there.",
  str_homestory_N19chuanshanjia_90010101_11_dialog_content = "Are you two familiar with this place, by any chance? Hmm, according to my years of knowledge and experience...",
  str_homestory_N19chuanshanjia_90010101_12_dialog_content = "I can only assume that you are in charge here, yes?",
  str_homestory_N19chuanshanjia_90010101_13_dialog_content = "How did you know?",
  str_homestory_N19chuanshanjia_90010101_14_dialog_content = "W-Wait, Vice, You can hear its thoughts, too?",
  str_homestory_N19chuanshanjia_90010101_15_dialog_content = "What do you mean by \"thoughts\"? It's clearly talking to us...",
  str_homestory_N19chuanshanjia_90010101_16_dialog_content = "...",
  str_homestory_N19chuanshanjia_90010101_17_dialog_content = "<size=65>Oh my gosh it's talking!</size>",
  str_homestory_N19chuanshanjia_90010101_18_dialog_content = "I'm indeed talking, yes.",
  str_homestory_N19chuanshanjia_90010101_19_dialog_content = "And for the record, my name is <color=#FFB400>Sahn</color>. Please refrain from referring to me as \"it\" from now on, thank you.",
  str_homestory_N19chuanshanjia_90010101_20_dialog_content = "Ah! Its name is Sahn!",
  str_homestory_N19chuanshanjia_90010101_21_dialog_content = "That's \"his,\" not \"its\"! Sigh, I can tell that you are young for your kind, but please show your elders a bit more respect.",
  str_homestory_N19chuanshanjia_90010101_22_dialog_content = "I-I'm really sorry. Judging from your long and thick beard, I'm sure you have years of wisdom and experience to share.",
  str_homestory_N19chuanshanjia_90010101_23_dialog_content = "An animal that can speak... Could he one of those <color=#FFB400>demi-humans</color> from the legends?",
  str_homestory_N19chuanshanjia_90010101_24_dialog_content = "Legends?",
  str_homestory_N19chuanshanjia_90010101_25_dialog_content = "What happened to the demi-humans?",
  str_homestory_N19chuanshanjia_90010101_26_dialog_content = "*Coughs* Er, you'll have to forgive my friend, Sahn. I think it's just because it's been a long time since she's seen a Lithic Pangalo.",
  str_homestory_N19chuanshanjia_90010101_27_dialog_content = "Really? Because she seems quite shocked at the notion of a talking animal, if you ask me!",
  str_homestory_N19chuanshanjia_90010101_28_dialog_content = "W-We know lots of talking animals! Right, Vice?",
  str_homestory_N19chuanshanjia_90010101_29_dialog_content = "Huh?",
  str_homestory_N19chuanshanjia_90010101_30_dialog_content = "(I don't think Sahn knows that the demi-humans aren't around anymore...)",
  str_homestory_N19chuanshanjia_90010101_31_dialog_content = "...",
  str_homestory_N19chuanshanjia_90010101_32_dialog_content = "Ah! R-Right!",
  str_homestory_N19chuanshanjia_90010101_33_dialog_content = "Do you think I was born yesterday? It's very obvious that she hesitated just now!",
  str_homestory_N19chuanshanjia_90010101_34_dialog_content = "Er, yes, well... It's a pleasure to meet you, Sahn. My name is Vice, and this is PlayerName.",
  str_homestory_N19chuanshanjia_90010101_35_dialog_content = "He's in charge here, and would never lie to you.",
  str_homestory_N19chuanshanjia_90010101_36_dialog_content = "The talking animals he mentioned are our friends.",
  str_homestory_N19chuanshanjia_90010101_37_dialog_content = "If you're still not convinced, then PlayerName will just have to bring them over for you to see.",
  str_homestory_N19chuanshanjia_90010101_38_dialog_content = "Let me think...",
  str_homestory_N19chuanshanjia_90010101_39_dialog_content = "(Didn't I see <color=#FFB400>Korgon</color> near the edge of the woods earlier? I can just bring him here!)",
  str_homestory_N19chuanshanjia_90010101_40_dialog_content = "Ah! Y-Yes! Please wait here for a moment, Sahn!",
  str_homestory_N19chuanshanjia_90010101_41_dialog_content = "(Don't say anything about the demi-humans while I'm gone, understand?)",
  str_homestory_N19chuanshanjia_90010101_42_dialog_content = "(O-Of course! Just hurry back, okay?)",
  str_homestory_N19chuanshanjia_90010111_1_dialog_content = "Let's find it. Chop-chop!",
  str_homestory_N19chuanshanjia_90010102_1_dialog_content = "Hey! Korgon!",
  str_homestory_N19chuanshanjia_90010102_2_dialog_content = "Yo! I was just looking for you, boss!",
  str_homestory_N19chuanshanjia_90010102_3_dialog_content = "How many times do I have to tell you to stop calling me \"boss\"?",
  str_homestory_N19chuanshanjia_90010102_4_dialog_content = "Ha! Good one, boss! Anyway, you got any good <color=#FFB400>wood</color> on your hands?",
  str_homestory_N19chuanshanjia_90010102_5_dialog_content = "Wood?",
  str_homestory_N19chuanshanjia_90010102_6_dialog_content = "They're thinkin' of building a small harbor on Sharkfang Island. That way, they won't have to keep dragging boats onto the shore all the time.",
  str_homestory_N19chuanshanjia_90010102_7_dialog_content = "You sure are busy. But let's put this wood business on hold for a second.",
  str_homestory_N19chuanshanjia_90010102_8_dialog_content = "I want to introduce you to someone first. You don't need to say much, and try not to scare him or anything.",
  str_homestory_N19chuanshanjia_90010102_9_dialog_content = "Meeting someone? Not a problem! But this wood's not gonna gather itself, boss... Let's do this tomorrow, yeah?",
  str_homestory_N19chuanshanjia_90010102_10_dialog_content = "Tomorrow? That won't do, I...",
  str_homestory_N19chuanshanjia_90010102_11_dialog_content = "Sigh... Fine, I'll help you gather some wood. How much do you need?",
  str_homestory_N19chuanshanjia_90010102_12_dialog_content = "<color=#FFB400>10</color> pieces of them ought to do it. I'll pay for 'em too, so don't worry!",
  str_homestory_N19chuanshanjia_90010102_13_dialog_content = "Right away!",
  str_homestory_N19chuanshanjia_90010112_1_dialog_content = "10 pieces of wood will do.",
  str_homestory_N19chuanshanjia_90010103_1_dialog_content = "Did ya gather enough wood?",
  str_homestory_N19chuanshanjia_90010103_2_dialog_content = "This should work! ({1}/{2})",
  str_homestory_N19chuanshanjia_90010103_3_dialog_content = "That's the boss for ya! Couldn't have done it better myself!",
  str_homestory_N19chuanshanjia_90010103_4_dialog_content = "Now when you meet him, try not to say anything strange. Just smile and nod for the most part and we'll be okay.",
  str_homestory_N19chuanshanjia_90010103_5_dialog_content = "You keep talkin' about this guy, but you still haven't told me who he is, boss! He's not some kind of weirdo, is he?",
  str_homestory_N19chuanshanjia_90010103_6_dialog_content = "You know I haven't talked to THOSE kinds of people in years, boss...",
  str_homestory_N19chuanshanjia_90010103_7_dialog_content = "He's an animal that speaks our language, just don't scare him and we'll be good.",
  str_homestory_N19chuanshanjia_90010103_8_dialog_content = "All I'm saying is, whenever you open your mouth to talk, your razor-sharp teeth can be a little... off-putting.",
  str_homestory_N19chuanshanjia_90010103_9_dialog_content = "Yeah, yeah, I catch your drift, boss.",
  str_homestory_N19chuanshanjia_90010103_10_dialog_content = "Not yet.",
  str_homestory_N19chuanshanjia_90010104_1_dialog_content = "I'm back!",
  str_homestory_N19chuanshanjia_90010104_2_dialog_content = "Oh, thank goodness! I was running out of things to talk about. He keeps asking all kinds of questions... I almost couldn't keep up the facade any longer.",
  str_homestory_N19chuanshanjia_90010104_3_dialog_content = "Look, Sahn!",
  str_homestory_N19chuanshanjia_90010104_4_dialog_content = "Greetings!",
  str_homestory_N19chuanshanjia_90010104_5_dialog_content = "H-He's going to eat me alive!!",
  str_homestory_N19chuanshanjia_90010104_6_dialog_content = "PlayerName... Why did you have to bring that guy, of all people?!",
  str_homestory_N19chuanshanjia_90010104_7_dialog_content = "What do you mean, \"that guy\"?!",
  str_homestory_N19chuanshanjia_90010104_8_dialog_content = "Did you guys forget that I'm a vegetarian? The only thing I see when I look at a small animal is something to pet and give treats to!",
  str_homestory_N19chuanshanjia_90010104_9_dialog_content = "It's not my fault I was born with a big mouth full of razor-sharp teeth!",
  str_homestory_N19chuanshanjia_90010104_10_dialog_content = "M-My apologies, friend. I was too quick to judge you by your appearance...",
  str_homestory_N19chuanshanjia_90010104_11_dialog_content = "Terrifying as your smile may be, I must say... Your teeth are some of the brightest and whitest that I have ever seen!",
  str_homestory_N19chuanshanjia_90010104_12_dialog_content = "R-Really? Finally, someone who appreciates my teeth!",
  str_homestory_N19chuanshanjia_90010104_13_dialog_content = "My shark teeth replace themselves often. I can crush my old teeth into powder and gift it to you to use for cooking!",
  str_homestory_N19chuanshanjia_90010104_14_dialog_content = "Th-That won't be necessary, thank you...",
  str_homestory_N19chuanshanjia_90010104_15_dialog_content = "Anyways, feel free to come visit Sharkfang Island any time!",
  str_homestory_N19chuanshanjia_90010104_16_dialog_content = "The scenery's the best there, especially during the daytime, when the sun shimmers on the waves.",
  str_homestory_N19chuanshanjia_90010104_17_dialog_content = "Ah, but I fear I must decline your gracious invitation, as well. You see, our kind... are particularly averse to large bodies of water.",
  str_homestory_N19chuanshanjia_90010104_18_dialog_content = "We're much more at home in the mountains. If you wish to visit us in the future, you can find us here.",
  str_homestory_N19chuanshanjia_90010104_19_dialog_content = "We decided to come here for a visit because we've been isolated in the mountains for too long. My clanmates wanted to see the outside world.",
  str_homestory_N19chuanshanjia_90010104_20_dialog_content = "I only hope that this place is more peaceful than others... My clanmates and I have endured so much hardship...",
  str_homestory_N19chuanshanjia_90010104_21_dialog_content = "So that's why you guys have always run off at the first sight of other species!",
  str_homestory_N19chuanshanjia_90010104_22_dialog_content = "I can assure you that Cloud Gardens is perfectly safe.",
  str_homestory_N19chuanshanjia_90010104_23_dialog_content = "Then I will return to my clanmates and tell them of this place at once!",
  str_homestory_N19chuanshanjia_90010104_24_dialog_content = "W-Wait! I didn't get to touch your scales!",
  str_homestory_N19chuanshanjia_90010104_25_dialog_content = "I'm sure you'll have another chance someday, Korgon.",
  str_homestory_N19chuanshanjia_90010104_26_dialog_content = "But first, you'll have to put that smile of yours away...",
  str_homestory_N19chuanshanjia_90010104_27_dialog_content = "... It really isn't my fault, you know.",
  str_homestory_N19chuanshanjia_90010201_1_dialog_content = "Hmm? You aren't Sahn, are you?",
  str_homestory_N19chuanshanjia_90010201_2_dialog_content = "Eep! I'm <color=#FFB400>Jiji</color>, wearer of the sturdiest, comfiest headband in all the land!",
  str_homestory_N19chuanshanjia_90010201_3_dialog_content = "Sahn told us of your peaceful and amicable ways, so I came right away!",
  str_homestory_N19chuanshanjia_90010201_4_dialog_content = "Tell me, what do you think of my headband? Eep!",
  str_homestory_N19chuanshanjia_90010201_5_option_content = "It's nice.",
  str_homestory_N19chuanshanjia_90010201_6_dialog_content = "What a lukewarm response...",
  str_homestory_N19chuanshanjia_90010201_7_option_content = "It's fantastic!",
  str_homestory_N19chuanshanjia_90010201_8_dialog_content = "It's very feminine.",
  str_homestory_N19chuanshanjia_90010201_9_dialog_content = "It's my most prized possession! Just look at this craftsmanship! This quality!",
  str_homestory_N19chuanshanjia_90010201_10_dialog_content = "A-Anyway... Now that you're here, is there anything I can help you with?",
  str_homestory_N19chuanshanjia_90010201_11_dialog_content = "Eep! Yes, actually! I just came up with a brand-new joke, and I came to share it with you!",
  str_homestory_N19chuanshanjia_90010201_12_dialog_content = "After all, I'm quite the comedic genius amongst the Pangalos!",
  str_homestory_N19chuanshanjia_90010201_13_dialog_content = "My dream is to become the greatest comedian in the world, so that I can spread unbridled joy and side-splitting laughter to all!",
  str_homestory_N19chuanshanjia_90010201_14_dialog_content = "A joke? Okay, let's hear it!",
  str_homestory_N19chuanshanjia_90010201_15_dialog_content = "Very well, then! Keep your ears open, get ready for it! Eep!",
  str_homestory_N19chuanshanjia_90010201_16_dialog_content = "A long, long time ago, there was a brave warrior.",
  str_homestory_N19chuanshanjia_90010201_17_dialog_content = "Her blade was cold, her hands were cold, her heart was cold, her personality was cool as a cucumber... In fact, her entire existence was cold as ice.",
  str_homestory_N19chuanshanjia_90010201_18_dialog_content = "And in the end, she froze to death.",
  str_homestory_N19chuanshanjia_90010201_19_dialog_content = "...",
  str_homestory_N19chuanshanjia_90010201_20_dialog_content = "<size=65>Hahahahaha!</size>",
  str_homestory_N19chuanshanjia_90010201_21_dialog_content = "...",
  str_homestory_N19chuanshanjia_90010201_22_dialog_content = "...",
  str_homestory_N19chuanshanjia_90010201_23_dialog_content = "<size=65>Ahaha.</size>",
  str_homestory_N19chuanshanjia_90010201_24_dialog_content = "Eep! Your face doesn't fool me! That was the most forced laugh that I've ever heard in my life!",
  str_homestory_N19chuanshanjia_90010201_25_dialog_content = "Er... Th-That's because my sense of humor is really weird! Why don't you try telling someone else your joke?",
  str_homestory_N19chuanshanjia_90010201_26_dialog_content = "Y-You'd better not be lying to me!",
  str_homestory_N19chuanshanjia_90010201_27_dialog_content = "I'm not, honest! I think I remember seeing Revy around here somewhere... Perfect!",
  str_homestory_N19chuanshanjia_90010202_1_dialog_content = "Hey, Revy? You look like you're spacing out.",
  str_homestory_N19chuanshanjia_90010202_2_dialog_content = "I'm counting the blades of grass on the ground.",
  str_homestory_N19chuanshanjia_90010202_3_dialog_content = "I-I see... Anyway, I have someone here who wants to tell you a joke, and I think you'd really enjoy it. Interested?",
  str_homestory_N19chuanshanjia_90010202_4_dialog_content = "Uh, sure.",
  str_homestory_N19chuanshanjia_90010202_5_dialog_content = "Eep! Wonderful! She looks like someone who can appreciate a little dry humor!",
  str_homestory_N19chuanshanjia_90010202_6_dialog_content = "I'm listening.",
  str_homestory_N19chuanshanjia_90010202_7_dialog_content = "A long, long time ago, there was a brave warrior.",
  str_homestory_N19chuanshanjia_90010202_8_dialog_content = "Her blade was cold, her hands were cold, her heart was cold, her personality was cool as a cucumber... In fact, her entire existence was cold as ice.",
  str_homestory_N19chuanshanjia_90010202_9_dialog_content = "And in the end, she froze to death.",
  str_homestory_N19chuanshanjia_90010202_10_dialog_content = "Oh.",
  str_homestory_N19chuanshanjia_90010202_11_dialog_content = "Eep! I-Is that all you have to say?!",
  str_homestory_N19chuanshanjia_90010202_12_dialog_content = "(Crap! It looks like not even Revy would laugh at a joke like that...)",
  str_homestory_N19chuanshanjia_90010202_13_dialog_content = "S-Sorry, Jiji! Let me go find someone else! After all, Revy was busy with something really important just now.",
  str_homestory_N19chuanshanjia_90010202_14_dialog_content = "Isn't that right, Revy?",
  str_homestory_N19chuanshanjia_90010202_15_dialog_content = "Huh?",
  str_homestory_N19chuanshanjia_90010202_16_dialog_content = "Let's go! Don't go anywhere, Jiji! I'll find the perfect audience for your joke, I promise!",
  str_homestory_N19chuanshanjia_90010203_1_dialog_content = "You're the only one here?",
  str_homestory_N19chuanshanjia_90010203_2_dialog_content = "What's that supposed to mean?",
  str_homestory_N19chuanshanjia_90010203_3_dialog_content = "You just... Don't seem like the type who enjoys jokes, that's all.",
  str_homestory_N19chuanshanjia_90010203_4_dialog_content = "Something about a cold blade and a cold heart...",
  str_homestory_N19chuanshanjia_90010203_5_dialog_content = "A \"cold blade\"? What are you talking about?",
  str_homestory_N19chuanshanjia_90010203_6_dialog_content = "Hmm? Dayna!",
  str_homestory_N19chuanshanjia_90010203_7_dialog_content = "Hahaha! Are you serious?!",
  str_homestory_N19chuanshanjia_90010203_8_dialog_content = "Are you... laughing?",
  str_homestory_N19chuanshanjia_90010203_9_dialog_content = "Is that your idea of a joke, Boatscrapper?",
  str_homestory_N19chuanshanjia_90010203_10_dialog_content = "N-No, it's not my joke at all. Someone else came up with it.",
  str_homestory_N19chuanshanjia_90010203_11_dialog_content = "Well, take me to them! I happen to be free right now.",
  str_homestory_N19chuanshanjia_90010211_1_dialog_content = "Hurry on, boatscrapper!",
  str_homestory_N19chuanshanjia_90010204_1_dialog_content = "Her? But she doesn't look like the kind who understands jokes...",
  str_homestory_N19chuanshanjia_90010204_2_dialog_content = "Are you kidding me? I heard all kinds of jokes back in Umbraton!",
  str_homestory_N19chuanshanjia_90010204_3_dialog_content = "Eep! Then let's give it a try. Listen carefully, now!",
  str_homestory_N19chuanshanjia_90010204_4_dialog_content = "A long, long time ago, there was a brave warrior. Her blade was cold...",
  str_homestory_N19chuanshanjia_90010204_5_dialog_content = "Oh... I get it.",
  str_homestory_N19chuanshanjia_90010204_6_dialog_content = "You don't seem particularly enthusiastic.",
  str_homestory_N19chuanshanjia_90010204_7_dialog_content = "Don't give up, Jiji! Keep going!",
  str_homestory_N19chuanshanjia_90010204_8_dialog_content = "Her hands were cold...",
  str_homestory_N19chuanshanjia_90010204_9_dialog_content = "...",
  str_homestory_N19chuanshanjia_90010204_10_dialog_content = "Her heart was cold.",
  str_homestory_N19chuanshanjia_90010204_10X1_dialog_content = "...",
  str_homestory_N19chuanshanjia_90010204_10X2_dialog_content = "In fact, her entire body was cold as ice.",
  str_homestory_N19chuanshanjia_90010204_10X3_dialog_content = "...",
  str_homestory_N19chuanshanjia_90010204_11_dialog_content = "... Pfffff.",
  str_homestory_N19chuanshanjia_90010204_12_dialog_content = "And in the end, she froze to death.",
  str_homestory_N19chuanshanjia_90010204_13_dialog_content = "<size=65>Hahahahaha! That joke was bone-dry!</size>",
  str_homestory_N19chuanshanjia_90010204_14_dialog_content = "<size=65>What?!?</size>",
  str_homestory_N19chuanshanjia_90010204_15_dialog_content = "Your delivery could use some work, but the joke was rock-solid! I needed a good laugh!",
  str_homestory_N19chuanshanjia_90010204_16_dialog_content = "I'm just glad someone finally found the humor in it!",
  str_homestory_N19chuanshanjia_90010204_17_dialog_content = "With jokes like that, you could make a few fans down in Umbraton!",
  str_homestory_N19chuanshanjia_90010204_18_dialog_content = "You'd probably even become famous.",
  str_homestory_N19chuanshanjia_90010204_19_dialog_content = "Eep!!! R-Really? I should go tell my clanmates!",
  str_homestory_N19chuanshanjia_90010204_20_dialog_content = "Hahahahaha! That joke was so dry! And so funny!",
  str_homestory_N19chuanshanjia_90010204_21_dialog_content = "I should ask PlayerName to tell it again when I get the chance.",
  str_homestory_N19chuanshanjia_90010301_1_dialog_content = "<size=65>Gwa! I finally found you!</size>",
  str_homestory_N19chuanshanjia_90010301_2_dialog_content = "Another Pangalo, huh? And this one doesn't seem too happy... Are you a friend of Sahn and Jiji, by any chance?",
  str_homestory_N19chuanshanjia_90010301_3_dialog_content = "Gwa! You must be PlayerName! I am <color=#FFB400>Tubby</color>, and I have come seeking vengeance!",
  str_homestory_N19chuanshanjia_90010301_4_dialog_content = "Because of you, Jiji rolled me up and kicked me around like a ball!",
  str_homestory_N19chuanshanjia_90010301_5_dialog_content = "W-Wait, then shouldn't you be taking your revenge out on Jiji, not me?",
  str_homestory_N19chuanshanjia_90010301_6_dialog_content = "Gwa! She said she only did it because you lied to her!",
  str_homestory_N19chuanshanjia_90010301_7_dialog_content = "Jiji came running up to me, saying something or another about a \"cold blade\" and \"cold hands\"...",
  str_homestory_N19chuanshanjia_90010301_8_dialog_content = "\"And then she froze to death.\"",
  str_homestory_N19chuanshanjia_90010301_9_dialog_content = "Gwa! Exactly! What an unfunny joke.",
  str_homestory_N19chuanshanjia_90010301_10_dialog_content = "But she kept insisting that it was the world's funniest joke, and that you had attested to it!",
  str_homestory_N19chuanshanjia_90010301_11_dialog_content = "She was furious when she found out that it was actually an awful joke, and that you lied to her about it!",
  str_homestory_N19chuanshanjia_90010301_12_dialog_content = "And then she turned me into a kicking ball.",
  str_homestory_N19chuanshanjia_90010301_13_dialog_content = "She kicked me around for so long, the world is still spinning before my eyes.",
  str_homestory_N19chuanshanjia_90010301_14_dialog_content = "So I thought to myself, if you were the one who started all of this... Then you should be the one getting punished, not me!",
  str_homestory_N19chuanshanjia_90010301_15_dialog_content = "P-Punishment?",
  str_homestory_N19chuanshanjia_90010301_16_dialog_content = "Gwa! That's right! You should curl up into a ball and let her kick you around instead!",
  str_homestory_N19chuanshanjia_90010301_17_dialog_content = "Wh-What kind of logic is that...?",
  str_homestory_N19chuanshanjia_90010301_18_dialog_content = "Well, do you have any better ideas?",
  str_homestory_N19chuanshanjia_90010301_19_dialog_content = "If only you had just been honest with Jiji about her joke from the very beginning, none of this would be happening.",
  str_homestory_N19chuanshanjia_90010301_20_dialog_content = "B-But everyone has their own sense of humor...",
  str_homestory_N19chuanshanjia_90010301_21_dialog_content = "I think giving Jiji encouragement is important!",
  str_homestory_N19chuanshanjia_90010301_22_dialog_content = "It might not have been as funny as she expected, but sometimes a little, white lie... I-I mean, it was still pretty funny! And Jiji needs our support!",
  str_homestory_N19chuanshanjia_90010301_23_dialog_content = "Jiji? Gwaaa! What about me?! Just look at the shape I'm in!",
  str_homestory_N19chuanshanjia_90010301_24_dialog_content = "I've been curled up for so long that I can't straighten my back anymore!",
  str_homestory_N19chuanshanjia_90010301_25_dialog_content = "What I need, is some alimentation!",
  str_homestory_N19chuanshanjia_90010301_26_dialog_content = "\"Alimentation\"...? You mean food?",
  str_homestory_N19chuanshanjia_90010301_27_dialog_content = "Correct! Something <color=#FFB400>sweet</color> would work best, I think.",
  str_homestory_N19chuanshanjia_90010301_28_dialog_content = "Desserts, huh? I think I saw a <color=#FFB400>Chubb Merchant</color> going towards the woods... Let's go see what we can do for you.",
  str_homestory_N19chuanshanjia_90010311_1_dialog_content = "You'll find something sweet, won't you?",
  str_homestory_N19chuanshanjia_90010302_1_dialog_content = "Desserts? All out. Chubb.",
  str_homestory_N19chuanshanjia_90010302_2_dialog_content = "All out?",
  str_homestory_N19chuanshanjia_90010302_3_dialog_content = "This isn't some one-stop-shop for all your snack needs! You have to place an order first! Chubb!",
  str_homestory_N19chuanshanjia_90010302_4_dialog_content = "Place an order...?",
  str_homestory_N19chuanshanjia_90010302_5_dialog_content = "Chubb! That's right! See? <color=#FFB400>Vice</color> has an order for a cake right here!",
  str_homestory_N19chuanshanjia_90010302_6_dialog_content = "Vice! Of course! Do you know where she is?",
  str_homestory_N19chuanshanjia_90010302_7_dialog_content = "By the river. Chubb!",
  str_homestory_N19chuanshanjia_90010302_8_dialog_content = "Thanks! Chubb!",
  str_homestory_N19chuanshanjia_90010302_9_dialog_content = "Don't mention it! Chubb!",
  str_homestory_N19chuanshanjia_90010302_10_dialog_content = "Huh?",
  str_homestory_N19chuanshanjia_90010312_1_dialog_content = "By the river. Vice, Chubb.",
  str_homestory_N19chuanshanjia_90010303_1_dialog_content = "Hey, Vice? What's that on your face...?",
  str_homestory_N19chuanshanjia_90010303_2_dialog_content = "Huh?",
  str_homestory_N19chuanshanjia_90010303_3_dialog_content = "Were you just eating cake?",
  str_homestory_N19chuanshanjia_90010303_4_dialog_content = "How did you know?",
  str_homestory_N19chuanshanjia_90010303_5_dialog_content = "Argh, I was too late!",
  str_homestory_N19chuanshanjia_90010303_6_dialog_content = "Guilty as charged, hehe... You really wanted cake that badly?",
  str_homestory_N19chuanshanjia_90010303_7_dialog_content = "It's a long story... I just need some cake right now, even just a small piece will do.",
  str_homestory_N19chuanshanjia_90010303_8_dialog_content = "When I went to pick up my cake, I saw <color=#FFB400>Korgon</color> placing an order for some, as well. I have no idea what for, though...",
  str_homestory_N19chuanshanjia_90010303_9_dialog_content = "But I saw him making his way to <color=#FFB400>Hyacinth Square</color> afterward.",
  str_homestory_N19chuanshanjia_90010303_10_dialog_content = "Hyacinth Square, huh? Got it!",
  str_homestory_N19chuanshanjia_90010313_1_dialog_content = "Hurry up now! Or he will finish eating it!",
  str_homestory_N19chuanshanjia_90010304_1_dialog_content = "Hey! I finally found you!",
  str_homestory_N19chuanshanjia_90010304_2_dialog_content = "What's up, boss?",
  str_homestory_N19chuanshanjia_90010304_3_dialog_content = "Do you still have any cake left?",
  str_homestory_N19chuanshanjia_90010304_4_dialog_content = "Oh? I didn't know you had a sweet tooth, boss?",
  str_homestory_N19chuanshanjia_90010304_5_dialog_content = "Ah! Yes, I do.",
  str_homestory_N19chuanshanjia_90010304_6_dialog_content = "Huh? Nah, that can't be right. I remember you telling me that you didn't care for sweets.",
  str_homestory_N19chuanshanjia_90010304_7_dialog_content = "You're right, but... It's kind of a long story.",
  str_homestory_N19chuanshanjia_90010304_8_dialog_content = "Don't sweat it, boss! I totally understand! Every man's got his own secrets...",
  str_homestory_N19chuanshanjia_90010304_9_dialog_content = "I take it you've got a little critter to feed too?",
  str_homestory_N19chuanshanjia_90010304_10_dialog_content = "H-Huh? Er... Right, you could say that...",
  str_homestory_N19chuanshanjia_90010304_11_dialog_content = "Anyway, do you think you could spare a little piece of cake...?",
  str_homestory_N19chuanshanjia_90010304_12_dialog_content = "No problem!",
  str_homestory_N19chuanshanjia_90010314_1_dialog_content = "It's not much, but it should be enough. What do you say, boss?",
  str_homestory_N19chuanshanjia_90010305_1_dialog_content = "I'm back! And I brought cake!",
  str_homestory_N19chuanshanjia_90010305_2_dialog_content = "Hold on!",
  str_homestory_N19chuanshanjia_90010305_3_dialog_content = "What's wrong?",
  str_homestory_N19chuanshanjia_90010305_4_dialog_content = "This cake hasn't been properly <color=#FFB400>seasoned</color>, has it?",
  str_homestory_N19chuanshanjia_90010305_5_dialog_content = "\"Seasoned\"...?",
  str_homestory_N19chuanshanjia_90010305_6_dialog_content = "While a cake's sweetness is often its main flavor, other flavors are just as important!",
  str_homestory_N19chuanshanjia_90010305_7_dialog_content = "Such as? I don't think it'll be easy to find any ready-made ingredients out here...",
  str_homestory_N19chuanshanjia_90010305_8_dialog_content = "There's no need, we've got plenty here!",
  str_homestory_N19chuanshanjia_90010305_9_dialog_content = "Here... where?",
  str_homestory_N19chuanshanjia_90010305_10_dialog_content = "The soil beneath us, of course.",
  str_homestory_N19chuanshanjia_90010305_11_dialog_content = "S-Soil...?!",
  str_homestory_N19chuanshanjia_90010305_12_dialog_content = "Our kind dig through mountains day in day out, and often end up consuming soil in the process.",
  str_homestory_N19chuanshanjia_90010305_13_dialog_content = "Different kinds of soil have different flavors. Personally, I like to add a scoop of grassy soil to my food for a slightly astringent taste. It's the best!",
  str_homestory_N19chuanshanjia_90010305_14_dialog_content = "Ah, just thinking about adding some to that piece of cake... My mouth's already starting to water!",
  str_homestory_N19chuanshanjia_90010305_15_dialog_content = "The world can be a really strange place sometimes...",
  str_homestory_N19chuanshanjia_90010305_16_dialog_content = "In any case, you have my thanks! Now then, I'm off to find some suitable soil for this cake, so I can share some with Jiji as a peace offering!",
  str_homestory_N19chuanshanjia_90010305_17_dialog_content = "Perhaps then, I could convince her to stop kicking me around! Gwa!",
  str_homestory_N19chuanshanjia_90010305_18_dialog_content = "... I guess there's a kind of cake for everyone out there.",
  str_homestory_N19chuanshanjia_90010401_1_dialog_content = "I heard you beat Tubby! Beat him good, I hear!",
  str_homestory_N19chuanshanjia_90010401_2_dialog_content = "Misunderstanding things seems to be a trait of your kind...",
  str_homestory_N19chuanshanjia_90010401_3_dialog_content = "Za! Tubby stormed off a few days ago, saying he was going to settle a score with you! Settle a score!",
  str_homestory_N19chuanshanjia_90010401_4_dialog_content = "But then he came back all happy and carefree! Said he didn't do a thing! Not a single thing!",
  str_homestory_N19chuanshanjia_90010401_5_dialog_content = "You must've beat him silly! Silly, silly!",
  str_homestory_N19chuanshanjia_90010401_6_dialog_content = "I-I didn't do anything like that! I just shared a piece of cake with him, that's all!",
  str_homestory_N19chuanshanjia_90010401_7_dialog_content = "Za! You must be quite the fighter! A skilled warrior, indeed!",
  str_homestory_N19chuanshanjia_90010401_8_dialog_content = "I'm <color=#FFB400>Fussy</color>. As a Lithic Pangalo warrior, I hereby challenge you to battle! To battle!",
  str_homestory_N19chuanshanjia_90010401_9_dialog_content = "You guys don't listen much to what others say, do you...?",
  str_homestory_N19chuanshanjia_90010401_10_dialog_content = "Sorry to disappoint you, Fussy, but I'm not a fighter in the least. You'll have to battle with someone else.",
  str_homestory_N19chuanshanjia_90010401_11_dialog_content = "Za? You don't wish to fight me?",
  str_homestory_N19chuanshanjia_90010401_12_dialog_content = "Is it because you're so powerful that if you attacked, I'd be instantly smashed?",
  str_homestory_N19chuanshanjia_90010401_13_dialog_content = "Then just send your strongest disciple in your place! Your very best disciple!! Za!!!",
  str_homestory_N19chuanshanjia_90010401_14_dialog_content = "D-Disciple...?",
  str_homestory_N19chuanshanjia_90010401_15_dialog_content = "Yes! If you won't fight me for fear of harming me, then allow your disciple to fight in your stead! Za!",
  str_homestory_N19chuanshanjia_90010401_16_dialog_content = "Are Pangalos capable of listening to others speak?",
  str_homestory_N19chuanshanjia_90010401_17_dialog_content = "Of course we are! Now send for your strongest disciple! I shall be waiting here in anticipation!",
  str_homestory_N19chuanshanjia_90010401_18_dialog_content = "Fine, I suppose...",
  str_homestory_N19chuanshanjia_90010401_19_dialog_content = "Looks like I have another misunderstanding on my hands... I'll just go find someone random, I guess.",
  str_homestory_N19chuanshanjia_90010401_20_dialog_content = "Za! What are you muttering about? What is it?",
  str_homestory_N19chuanshanjia_90010401_21_dialog_content = "I'm going, I'm going! I'll see if I can find anyone by the river.",
  str_homestory_N19chuanshanjia_90010402_1_dialog_content = "What're you looking at? Chubb.",
  str_homestory_N19chuanshanjia_90010402_2_dialog_content = "Sigh... You don't look like much of a fighter.",
  str_homestory_N19chuanshanjia_90010402_3_dialog_content = "We Chubbs are not suited to fighting, no. Chubb.",
  str_homestory_N19chuanshanjia_90010402_4_dialog_content = "This is a place of peace, after all. Chubb.",
  str_homestory_N19chuanshanjia_90010402_5_dialog_content = "Ah, there's Barton, Chubb!",
  str_homestory_N19chuanshanjia_90010402_6_dialog_content = "He's surveying the terrain for a place to build a training camp for new recruits. Chubb!",
  str_homestory_N19chuanshanjia_90010402_7_dialog_content = "He'll do!",
  str_homestory_N19chuanshanjia_90010402_8_dialog_content = "Chubb?",
  str_homestory_N19chuanshanjia_90010411_1_dialog_content = "Nearby. Barton, Chubb.",
  str_homestory_N19chuanshanjia_90010403_1_dialog_content = "We can pack the earth here for training grounds and lay the foundations for a barracks over there...",
  str_homestory_N19chuanshanjia_90010403_2_dialog_content = "There you are, Barton!",
  str_homestory_N19chuanshanjia_90010403_3_dialog_content = "Ah, your timing couldn't be better! I need your help with something, and I'll need to commandeer this land to do it!",
  str_homestory_N19chuanshanjia_90010403_4_dialog_content = "C-Commandeer..?",
  str_homestory_N19chuanshanjia_90010403_5_dialog_content = "It's way overly peaceful here, which simply won't do!",
  str_homestory_N19chuanshanjia_90010403_6_dialog_content = "You're all like sitting lambs in a den of wolves!",
  str_homestory_N19chuanshanjia_90010403_7_dialog_content = "You need guards! You need soldiers!",
  str_homestory_N19chuanshanjia_90010403_8_dialog_content = "So naturally, you need a training camp first and foremost.",
  str_homestory_N19chuanshanjia_90010403_9_dialog_content = "Leave it to me! I'll establish this regiment, and I'll train them too!",
  str_homestory_N19chuanshanjia_90010403_10_dialog_content = "And believe me, I won't rest until the job is done! That way, my own legion's numbers might go up, as well...",
  str_homestory_N19chuanshanjia_90010403_11_dialog_content = "I'm pretty sure that's the only reason you're doing this...",
  str_homestory_N19chuanshanjia_90010403_12_dialog_content = "Never mind, now's not the time.",
  str_homestory_N19chuanshanjia_90010403_13_dialog_content = "Let's set this matter aside for the moment. Do you fancy a battle with someone?",
  str_homestory_N19chuanshanjia_90010403_14_dialog_content = "I've got myself an eager recruit already?",
  str_homestory_N19chuanshanjia_90010403_15_dialog_content = "Where are they?",
  str_homestory_N19chuanshanjia_90010403_16_dialog_content = "Right over there.",
  str_homestory_N19chuanshanjia_90010403_17_dialog_content = "Alright, time for a lesson in humility! What kind of new recruit challenges the instructor on their first day?",
  str_homestory_N19chuanshanjia_90010403_18_dialog_content = "Wait, Barton, I'm not done!",
  str_homestory_N19chuanshanjia_90010412_1_dialog_content = "You're finally here! We're about to fight!",
  str_homestory_N19chuanshanjia_90010404_1_dialog_content = "So you're the little upstart who doesn't know their own place, huh?",
  str_homestory_N19chuanshanjia_90010404_2_dialog_content = "Za! You're even more arrogant than PlayerName! Far more arrogant!",
  str_homestory_N19chuanshanjia_90010404_3_dialog_content = "I presume you're also a skilled fighter, yes? Za!",
  str_homestory_N19chuanshanjia_90010404_4_dialog_content = "I'm too late, they're both raring to go!",
  str_homestory_N19chuanshanjia_90010404_5_dialog_content = "I don't need to be a skilled fighter to put an insubordinate recruit in their place!",
  str_homestory_N19chuanshanjia_90010404_6_dialog_content = "I've gotta say, you look a little strange... although I could say that about a lot of the residents here.",
  str_homestory_N19chuanshanjia_90010404_7_dialog_content = "To hell with it! If your arms and legs work just fine, and that tail of yours isn't just for show, then I'll make a soldier out of you yet!",
  str_homestory_N19chuanshanjia_90010404_8_dialog_content = "Now, then, let the training begin!",
  str_homestory_N19chuanshanjia_90010404_9_dialog_content = "As expected of a true master's disciple! The harshness of your words is just as powerful as the confidence you exude!",
  str_homestory_N19chuanshanjia_90010404_10_dialog_content = "But don't count your chickens before they hatch! You have to win against me first! Zaaaa!",
  str_homestory_N19chuanshanjia_90010404_11_dialog_content = "<size=65>Wait!</size>",
  str_homestory_N19chuanshanjia_90010404_12_dialog_content = "Fighting here is a little too dangerous. Why don't you two...",
  str_homestory_N19chuanshanjia_90010404_13_dialog_content = "Have a contest of \"<color=#FFB400>auras</color>,\" instead?",
  str_homestory_N19chuanshanjia_90010404_14_dialog_content = "... Za? Auras?",
  str_homestory_N19chuanshanjia_90010404_15_dialog_content = "Auras?",
  str_homestory_N19chuanshanjia_90010404_16_dialog_content = "It's like... A combination of your will to fight, your physical state, your combat capabilities, as well as other things.",
  str_homestory_N19chuanshanjia_90010404_17_dialog_content = "I'm a Caelestite, remember? I can use my powers to see your auras and determine which of you is stronger.",
  str_homestory_N19chuanshanjia_90010404_18_dialog_content = "I-Is that even possible?!",
  str_homestory_N19chuanshanjia_90010404_19_dialog_content = "It is... Caelestites are extremely perceptive. This idea sounds good to me.",
  str_homestory_N19chuanshanjia_90010404_20_dialog_content = "Then let's begin.",
  str_homestory_N19chuanshanjia_90010404_21_dialog_content = "<anim type=Shake><size=65>Grrrrrr—</size></anim>",
  str_homestory_N19chuanshanjia_90010404_22_dialog_content = "<anim type=Shake><size=65>Zaaaaa—</size></anim>",
  str_homestory_N19chuanshanjia_90010404_23_dialog_content = "Wh-What is this?! I can't tell whose aura is stronger!",
  str_homestory_N19chuanshanjia_90010404_24_dialog_content = "You're both insanely powerful!",
  str_homestory_N19chuanshanjia_90010404_25_dialog_content = "I see!",
  str_homestory_N19chuanshanjia_90010404_26_dialog_content = "Impressive!",
  str_homestory_N19chuanshanjia_90010404_27_dialog_content = "It looked like a draw to me, guys.",
  str_homestory_N19chuanshanjia_90010404_28_dialog_content = "(Another Pangalo, another lie...)",
  str_homestory_N19chuanshanjia_90010404_29_dialog_content = "PlayerName, you really found me an awesome recruit! There's a lot of potential in this one!",
  str_homestory_N19chuanshanjia_90010404_30_dialog_content = "What do you say? Wanna work for me? Illumina gives great benefits!",
  str_homestory_N19chuanshanjia_90010404_31_dialog_content = "Za! A disciple with his own disciples... Truly, I'm in the presence of masters!",
  str_homestory_N19chuanshanjia_90010404_32_dialog_content = "I must return to the mountains and train a few more years! I must take my leave now, farewell!",
  str_homestory_N19chuanshanjia_90010404_33_dialog_content = "What a hardworking recruit! A sad day for Illumina's military, indeed...",
  str_homestory_N19chuanshanjia_90010404_34_dialog_content = "Once my training camp is built, I'll be sure to recruit her into my ranks! Until next time, PlayerName!",
  str_homestory_N19chuanshanjia_90010404_35_dialog_content = "I can't believe that whole thing went down like it did...",
  str_homestory_N19chuanshanjia_90010501_1_dialog_content = "My friend!",
  str_homestory_N19chuanshanjia_90010501_2_dialog_content = "Huh? Are you talking to me?",
  str_homestory_N19chuanshanjia_90010501_3_dialog_content = "Du-du! Everyone spoke of your helpfulness, so I came to see you as well!",
  str_homestory_N19chuanshanjia_90010501_4_dialog_content = "Let me guess... Your name is \"Du-Du\" or something, right?",
  str_homestory_N19chuanshanjia_90010501_5_dialog_content = "It's actually <color=#FFB400>Greenbelly</color>! Du-du!",
  str_homestory_N19chuanshanjia_90010501_6_dialog_content = "I see... By \"everyone,\" are you referring to all the Pangalos that came over the last few days?",
  str_homestory_N19chuanshanjia_90010501_7_dialog_content = "Indeed! They're all grateful towards you, so I came to deliver a token of thanks.",
  str_homestory_N19chuanshanjia_90010501_8_dialog_content = "A token of thanks? Like a gift?",
  str_homestory_N19chuanshanjia_90010501_9_dialog_content = "Du-du! A special drink, to be precise. Made from a secret family recipe!",
  str_homestory_N19chuanshanjia_90010501_10_dialog_content = "It may look ordinary...",
  str_homestory_N19chuanshanjia_90010501_11_dialog_content = "But you'll understand how special it is the moment it passes through your lips! Du-du!",
  str_homestory_N19chuanshanjia_90010501_12_dialog_content = "It'll feel somewhat warm as it slides down your throat, and once it reaches your belly, you'll experience a sense of extreme comfort...",
  str_homestory_N19chuanshanjia_90010501_13_dialog_content = "That sounds kinda interesting. Such a drink really exists?",
  str_homestory_N19chuanshanjia_90010501_14_dialog_content = "Du-du! Of course! Now then, would you like to try some?",
  str_homestory_N19chuanshanjia_90010501_15_dialog_content = "Yes! What do you need to make it?",
  str_homestory_N19chuanshanjia_90010501_16_dialog_content = "Du-du! It's a secret!",
  str_homestory_N19chuanshanjia_90010501_17_dialog_content = "First, I'll need some <color=#FFB400>salt</color>.",
  str_homestory_N19chuanshanjia_90010501_18_dialog_content = "I think I saw the <color=#FFB400>Chubb Merchant</color> wandering around near the woods. He should have some.",
  str_homestory_N19chuanshanjia_90010511_1_dialog_content = "Clock is ticking. Hurry up! Du-du.",
  str_homestory_N19chuanshanjia_90010502_1_dialog_content = "Salt? Yes, I have some. Chubb!",
  str_homestory_N19chuanshanjia_90010502_2_dialog_content = "But someone already ordered it all. I can't sell it as I wish, Chubb.",
  str_homestory_N19chuanshanjia_90010502_3_dialog_content = "I just need a tiny bit. Can't you spare a little?",
  str_homestory_N19chuanshanjia_90010502_4_dialog_content = "Let me see, Chubb.",
  str_homestory_N19chuanshanjia_90010502_5_dialog_content = "A spoonful should be okay by my calculations. Chubb!",
  str_homestory_N19chuanshanjia_90010502_6_dialog_content = "That's great!",
  str_homestory_N19chuanshanjia_90010502_7_dialog_content = "But you must make up the difference with <color=#FFB400>ore</color>. I need to meet my sale quota, Chubb!",
  str_homestory_N19chuanshanjia_90010502_8_dialog_content = "Not a problem, it's a deal!",
  str_homestory_N19chuanshanjia_90010512_1_dialog_content = "I said 10! Chubb!",
  str_homestory_N19chuanshanjia_90010503_1_dialog_content = "Enough ore?",
  str_homestory_N19chuanshanjia_90010503_2_dialog_content = "Here! The ores. ({1}/{2})",
  str_homestory_N19chuanshanjia_90010503_3_dialog_content = "That was quick! Chubb!",
  str_homestory_N19chuanshanjia_90010503_4_dialog_content = "Of course! PlayerName is very familiar with Cloud Gardens! Chubb!",
  str_homestory_N19chuanshanjia_90010503_5_dialog_content = "This is the salt. Don't lose it. Chubb.",
  str_homestory_N19chuanshanjia_90010503_6_dialog_content = "All packed tightly and firmly. Don't spill it, Chubb.",
  str_homestory_N19chuanshanjia_90010503_7_dialog_content = "Thank you so much!",
  str_homestory_N19chuanshanjia_90010503_8_dialog_content = "Not yet.",
  str_homestory_N19chuanshanjia_90010513_1_dialog_content = "Be careful not to spill it, Chubb!",
  str_homestory_N19chuanshanjia_90010504_1_dialog_content = "Here's the salt.",
  str_homestory_N19chuanshanjia_90010504_2_dialog_content = "That took a long time! Du-du!",
  str_homestory_N19chuanshanjia_90010504_3_dialog_content = "Yeah, there was a lot of this and that involved. If it weren't for this mysterious beverage...",
  str_homestory_N19chuanshanjia_90010504_4_dialog_content = "You'll be able to try it soon. I've got the rest of the ingredients ready to go, du-du!",
  str_homestory_N19chuanshanjia_90010504_5_dialog_content = "Let's get started!",
  str_homestory_N19chuanshanjia_90010504_6_dialog_content = "You must leave for now. This is a secret recipe, you know? Exclusive! Du-du!",
  str_homestory_N19chuanshanjia_90010504_7_dialog_content = "Oh, then let me <color=#FFB400>go walk around somewhere close by</color>.",
  str_homestory_N19chuanshanjia_90010504_8_dialog_content = "Go for a longer walk! Out by the riverside is good!",
  str_homestory_N19chuanshanjia_90010505_1_dialog_content = "You're finally here! The beverage is ready!",
  str_homestory_N19chuanshanjia_90010505_2_dialog_content = "Huh? It looks really normal. It's transparent and also doesn't smell of anything.",
  str_homestory_N19chuanshanjia_90010505_3_dialog_content = "I added a secret flavor to it! A special kind! It's invisible.",
  str_homestory_N19chuanshanjia_90010505_4_dialog_content = "A flavoring that's not visible in water... Is it that bag of salt?",
  str_homestory_N19chuanshanjia_90010505_5_dialog_content = "I like smart people! Du-du!",
  str_homestory_N19chuanshanjia_90010505_6_dialog_content = "Ah! Oh no, it's no longer a secret!",
  str_homestory_N19chuanshanjia_90010505_7_dialog_content = "You're telling me the only secret flavoring in this mysterious beverage is salt?!",
  str_homestory_N19chuanshanjia_90010505_8_dialog_content = "Your psychic ability is as shocking as Fussy described. Du-du!",
  str_homestory_N19chuanshanjia_90010505_9_dialog_content = "Indeed, only salt. Du-du.",
  str_homestory_N19chuanshanjia_90010505_10_dialog_content = "<size=65>Isn't it just plain salt water then?!</size>",
  str_homestory_N19chuanshanjia_90010505_11_dialog_content = "Shh! Don't let anyone hear that! Du-du!",
  str_homestory_N19chuanshanjia_90010505_12_dialog_content = "You know that there's an entire ocean-full of salt water, right?",
  str_homestory_N19chuanshanjia_90010505_13_dialog_content = "But we don't have this in the mountains! Du-du! All you find there is tasteless freshwater!",
  str_homestory_N19chuanshanjia_90010505_14_dialog_content = "One time, I was in a cave, and when I licked the condensation off a rock, it was salty.",
  str_homestory_N19chuanshanjia_90010505_15_dialog_content = "I've found this taste wonderful ever since! Du-du!",
  str_homestory_N19chuanshanjia_90010505_16_dialog_content = "(I guess salt is so common for us that we take it for granted.)",
  str_homestory_N19chuanshanjia_90010505_17_dialog_content = "(But for them...)",
  str_homestory_N19chuanshanjia_90010505_18_dialog_content = "Now that you mention it, I realize it too.",
  str_homestory_N19chuanshanjia_90010505_19_dialog_content = "Salt truly has a wonderful taste.",
  str_homestory_N19chuanshanjia_90010505_20_dialog_content = "Tell me about it! Me! Du-du! You must keep it a secret!",
  str_homestory_N19chuanshanjia_90010505_21_dialog_content = "Okay, okay.",
  str_homestory_N19chuanshanjia_90010505_22_dialog_content = "I have plenty of salt here. You can swing by anytime and grab some.",
  str_homestory_N19chuanshanjia_90010505_23_dialog_content = "Really? That's generous of you! Du-du!",
  str_homestory_N19chuanshanjia_90010505_24_dialog_content = "I also have a lot of beverages in other flavors that you can have a taste of next time.",
  str_homestory_N19chuanshanjia_90010505_25_dialog_content = "Yes! Yes! But I still think this salty water tastes the best!",
  str_homestory_N19chuanshanjia_90010505_26_dialog_content = "If you're going to drink it, then I'm taking it back! Du-du!",
  str_homestory_N19chuanshanjia_90010505_27_dialog_content = "Be careful out there!",
  str_homestory_N19chuanshanjia_90010505_28_dialog_content = "Salt, huh... Reminds me of that famous book quote.",
  str_homestory_N19chuanshanjia_90010505_29_dialog_content = "\"Love someone like you salt your food. Not too much, not too little.\"",
  str_homestory_N19chuanshanjia_90010505_30_dialog_content = "Maybe the actual secret to this drink is the ratio of salt and water.",
  str_homestory_N19chuanshanjia_90010601_1_dialog_content = "<anim type=Shake><size=65>Death is emptiness! Death is truth!</size></anim>",
  str_homestory_N19chuanshanjia_90010601_2_dialog_content = "It's way too noisy here... Vice, I'm leaving!",
  str_homestory_N19chuanshanjia_90010601_3_dialog_content = "What's that? I can't hear you! Well, whatever you say, I have to go!",
  str_homestory_N19chuanshanjia_90010601_4_dialog_content = "Vice, wait!",
  str_homestory_N19chuanshanjia_90010601_5_dialog_content = "Wow, that was fast. Anyways, this music—if you can call it that—is way too loud.",
  str_homestory_N19chuanshanjia_90010601_6_dialog_content = "Sigh, I thought I'd gotten used to Regina's performances, but I guess not.",
  str_homestory_N19chuanshanjia_90010601_7_dialog_content = "Can you even call that music? It's more like screaming with musical instruments.",
  str_homestory_N19chuanshanjia_90010601_8_dialog_content = "This is the bestest music in all the lands, mountains, and soil! Eep!",
  str_homestory_N19chuanshanjia_90010601_9_dialog_content = "The tempo, the melody, the arrangement, the vocals... I can't afford to miss any of it! Eep!",
  str_homestory_N19chuanshanjia_90010601_10_dialog_content = "... Are you serious?",
  str_homestory_N19chuanshanjia_90010601_11_dialog_content = "Yes, this amazing musician's name is Regina, right?",
  str_homestory_N19chuanshanjia_90010601_12_dialog_content = "Well, yes.",
  str_homestory_N19chuanshanjia_90010601_13_dialog_content = "She must be very popular.",
  str_homestory_N19chuanshanjia_90010601_14_dialog_content = "It's a little... Um, I don't know how to put it.",
  str_homestory_N19chuanshanjia_90010601_15_dialog_content = "What are you hiding? You seem unable to enjoy her music.",
  str_homestory_N19chuanshanjia_90010601_16_dialog_content = "That's right! Za!",
  str_homestory_N19chuanshanjia_90010601_17_dialog_content = "Sahn, Jiji, we just went to sneak a peek.",
  str_homestory_N19chuanshanjia_90010601_18_dialog_content = "Regina had no audience! Du!",
  str_homestory_N19chuanshanjia_90010601_19_dialog_content = "How can this be? How?",
  str_homestory_N19chuanshanjia_90010601_20_dialog_content = "It's true, za! Regina was performing alone.",
  str_homestory_N19chuanshanjia_90010601_21_dialog_content = "What a pity... Even from this far away, I can feel the discontent in Regina's singing.",
  str_homestory_N19chuanshanjia_90010601_22_dialog_content = "Du-du! Should we cheer for her?",
  str_homestory_N19chuanshanjia_90010601_23_dialog_content = "Good idea! Eep!",
  str_homestory_N19chuanshanjia_90010601_24_dialog_content = "But she looks a little scary. Going over there randomly would be weird, right? Gwa!",
  str_homestory_N19chuanshanjia_90010601_25_dialog_content = "Maybe we should first practice cheering.",
  str_homestory_N19chuanshanjia_90010601_26_dialog_content = "PlayerName, how do Aurorians cheer for others?",
  str_homestory_N19chuanshanjia_90010601_27_dialog_content = "I... I can go ask someone. As long as I can get out of here...",
  str_homestory_N19chuanshanjia_90010601_28_dialog_content = "Then we'll wait for your return.",
  str_homestory_N19chuanshanjia_90010601_29_dialog_content = "I'll <color=#FFB400>go ask Vice</color>. She should still be around.",
  str_homestory_N19chuanshanjia_90010602_1_dialog_content = "Phew, silence at last.",
  str_homestory_N19chuanshanjia_90010602_2_dialog_content = "Hey Vice, I need a favor.",
  str_homestory_N19chuanshanjia_90010602_3_dialog_content = "Don't tell me you still want me to listen to Regina's music!",
  str_homestory_N19chuanshanjia_90010602_4_dialog_content = "No, no, I have a question for you.",
  str_homestory_N19chuanshanjia_90010602_5_dialog_content = "Anything is fine as long as it doesn't involve listening to that music.",
  str_homestory_N19chuanshanjia_90010602_6_dialog_content = "What is the best way to cheer someone up? Preferably with lots of people.",
  str_homestory_N19chuanshanjia_90010602_7_dialog_content = "It sounds a lot like the kind of <color=#FFB400>cheering</color> that <color=#FFB400>Barbara</color> mentioned before.",
  str_homestory_N19chuanshanjia_90010602_8_dialog_content = "She happens to be hanging out by the river. Want to go ask her?",
  str_homestory_N19chuanshanjia_90010602_9_dialog_content = "That's great!",
  str_homestory_N19chuanshanjia_90010603_1_dialog_content = "Fishing is so difficult!",
  str_homestory_N19chuanshanjia_90010603_2_dialog_content = "Hi, Barbara! Out on a stroll?",
  str_homestory_N19chuanshanjia_90010603_3_dialog_content = "I'm fishing! It's quite a difficult task!",
  str_homestory_N19chuanshanjia_90010603_4_dialog_content = "I'm glad you're here. By the way, what's the best way to go about cheering someone on?",
  str_homestory_N19chuanshanjia_90010603_5_dialog_content = "I don't know, my belly's empty now!",
  str_homestory_N19chuanshanjia_90010603_6_dialog_content = "So that's why you're fishing?",
  str_homestory_N19chuanshanjia_90010603_7_dialog_content = "I'm craving sashimi like crazy! But fishing is so difficult!",
  str_homestory_N19chuanshanjia_90010603_8_dialog_content = "It's not too difficult. Let me do it!",
  str_homestory_N19chuanshanjia_90010603_9_dialog_content = "<color=#FFB400>Three fish</color> should be enough, right?",
  str_homestory_N19chuanshanjia_90010603_10_dialog_content = "Super enough!",
  str_homestory_N19chuanshanjia_90010604_1_dialog_content = "Fresh fish! Gonna get fresh fish!",
  str_homestory_N19chuanshanjia_90010604_2_dialog_content = "This is enough, right? ({1}/{2})",
  str_homestory_N19chuanshanjia_90010604_3_dialog_content = "Yep! Very fresh!",
  str_homestory_N19chuanshanjia_90010604_4_dialog_content = "You can eat your fill later. Now you can answer my question, right?",
  str_homestory_N19chuanshanjia_90010604_5_dialog_content = "If I want multiple people to cheer for a person, that's <color=#FFB400>cheering them on</color>, right?",
  str_homestory_N19chuanshanjia_90010604_6_dialog_content = "Is there any trick to it?",
  str_homestory_N19chuanshanjia_90010604_7_dialog_content = "It's \"<color=#FFB400>love</color>\"!",
  str_homestory_N19chuanshanjia_90010604_8_dialog_content = "Love? That's it?",
  str_homestory_N19chuanshanjia_90010604_9_dialog_content = "It's extremely important!",
  str_homestory_N19chuanshanjia_90010604_10_dialog_content = "If you show enough love, the other person will feel it for sure.",
  str_homestory_N19chuanshanjia_90010604_11_dialog_content = "That's it?",
  str_homestory_N19chuanshanjia_90010604_12_dialog_content = "Sincerity is better than any tricks!",
  str_homestory_N19chuanshanjia_90010604_13_dialog_content = "I-I'll try it...",
  str_homestory_N19chuanshanjia_90010604_14_dialog_content = "I'll fish for some more.",
  str_homestory_N19chuanshanjia_90010605_1_dialog_content = "From what I've learned, you guys just have to be sincere in expressing your love... and that should be it.",
  str_homestory_N19chuanshanjia_90010605_2_dialog_content = "But how do we express love?",
  str_homestory_N19chuanshanjia_90010605_3_dialog_content = "According to the professionals, if you really like the individual you're supporting, they'll definitely feel it.",
  str_homestory_N19chuanshanjia_90010605_4_dialog_content = "You just have to express yourselves fully.",
  str_homestory_N19chuanshanjia_90010605_5_dialog_content = "We understand Regina's love for music the most!",
  str_homestory_N19chuanshanjia_90010605_6_dialog_content = "Yes! That's the spirit!",
  str_homestory_N19chuanshanjia_90010605_7_dialog_content = "Then I'll go strategize with the others. Come see us cheer later!",
  str_homestory_N19chuanshanjia_90010605_8_dialog_content = "I have to go back...?",
  str_homestory_N19chuanshanjia_90010606_1_dialog_content = "My ears start ringing as soon as I come back here...",
  str_homestory_N19chuanshanjia_90010606_2_dialog_content = "<anim type=Shake><size=65>Unfair world! Burning heart!</size></anim>",
  str_homestory_N19chuanshanjia_90010606_3_dialog_content = "But it's like Sahn said. There's an undercurrent of resentment in both the lyrics and the rhythm.",
  str_homestory_N19chuanshanjia_90010606_4_dialog_content = "It seems Regina has a lot of thoughts she wants to express too...",
  str_homestory_N19chuanshanjia_90010606_5_dialog_content = "Are you trying to say something?",
  str_homestory_N19chuanshanjia_90010606_6_dialog_content = "Music! Don't stop! Eep!",
  str_homestory_N19chuanshanjia_90010606_7_dialog_content = "Za! We want music!",
  str_homestory_N19chuanshanjia_90010606_8_dialog_content = "Regina's music! The strongest! Du!",
  str_homestory_N19chuanshanjia_90010606_9_dialog_content = "Here's my latest song! Dedicated to my new listeners!",
  str_homestory_N19chuanshanjia_90010606_10_dialog_content = "<anim type=Shake><size=65>Like a Great Enemy's Come!</size></anim>",
  str_homestory_N19chuanshanjia_90010606_11_dialog_content = "<anim type=Shake><size=65>The real enemies aren't the Eclipsites!</size></anim>",
  str_homestory_N19chuanshanjia_90010606_12_dialog_content = "Aren't the Eclipsites!",
  str_homestory_N19chuanshanjia_90010606_13_dialog_content = "Aren't the Eclipsites!",
  str_homestory_N19chuanshanjia_90010606_14_dialog_content = "<anim type=Shake><size=65>The real enemies are our deepest, darkest thoughts!</size></anim>",
  str_homestory_N19chuanshanjia_90010606_15_dialog_content = "Deepest, darkest thoughts!",
  str_homestory_N19chuanshanjia_90010606_16_dialog_content = "Deepest, darkest! Thoughts!",
  str_homestory_N19chuanshanjia_90010606_17_dialog_content = "Darkest! Thoughts!",
  str_homestory_N19chuanshanjia_90010606_18_dialog_content = "I didn't expect the Pangalos to like this type of music.",
  str_homestory_N19chuanshanjia_90010606_19_dialog_content = "Truly a species with unique tastes...",
  str_homestory_N19chuanshanjia_90010606_20_dialog_content = "Did you hear that solo? That was wicked awesome!",
  str_homestory_N19chuanshanjia_90010606_21_dialog_content = "I'm full of power! I'm invincible!",
  str_homestory_N19chuanshanjia_90010606_22_dialog_content = "I-I'm about to fly!",
  str_homestory_N19chuanshanjia_90010606_23_dialog_content = "Why am I crying...?",
  str_homestory_N19chuanshanjia_90010606_24_dialog_content = "That solo's gonna repeat itself in my head for the next month!",
  str_homestory_N19chuanshanjia_90010606_25_dialog_content = "You guys...",
  str_homestory_N19chuanshanjia_90010606_26_dialog_content = "I've performed many shows, but this is my first time having an audience like you guys.",
  str_homestory_N19chuanshanjia_90010606_27_dialog_content = "That cheering method seemed a little familiar too.",
  str_homestory_N19chuanshanjia_90010606_28_dialog_content = "Ahem, that's not important. What's important is that they really really like your songs.",
  str_homestory_N19chuanshanjia_90010606_29_dialog_content = "True. I could feel their sincerity through their expressions and body language.",
  str_homestory_N19chuanshanjia_90010606_30_dialog_content = "Aah! They're surrounding us!",
  str_homestory_N19chuanshanjia_90010606_31_dialog_content = "Regina, on behalf of the Lithic Pangalos, I would like to express my sincere thanks.",
  str_homestory_N19chuanshanjia_90010606_32_dialog_content = "Autograph! Autograph! Eep!",
  str_homestory_N19chuanshanjia_90010606_33_dialog_content = "Can I have an autograph too?",
  str_homestory_N19chuanshanjia_90010606_34_dialog_content = "Za! Sahn, Tubby, Greenbelly! Stop hanging back! Get over here!",
  str_homestory_N19chuanshanjia_90010606_35_dialog_content = "Y-Yes, Lady Regina! I want an autograph too!",
  str_homestory_N19chuanshanjia_90010606_36_dialog_content = "Haha, I'm no lady! I'm just into rock'n roll!",
  str_homestory_N19chuanshanjia_90010606_37_dialog_content = "But the way you guys were cheering earlier...",
  str_homestory_N19chuanshanjia_90010606_38_dialog_content = "Did that \"deep-fry cream puff\" teach you that?",
  str_homestory_N19chuanshanjia_90010606_39_dialog_content = "Um! I taught them...",
  str_homestory_N19chuanshanjia_90010606_40_dialog_content = "So \"deep-fry cream puff\" taught you.",
  str_homestory_N19chuanshanjia_90010606_41_dialog_content = "Err...",
  str_homestory_N19chuanshanjia_90010606_42_dialog_content = "But they were very sincere, and I could tell that they enjoyed my music from the heart.",
  str_homestory_N19chuanshanjia_90010606_43_dialog_content = "Come! Autographs are no problem! A picture together is okay too!",
  str_homestory_N19chuanshanjia_90010606_44_dialog_content = "Really?!",
  str_homestory_N19chuanshanjia_90010606_45_dialog_content = "Me first! Me first!",
  str_homestory_N19chuanshanjia_90010606_46_dialog_content = "Why don't you all join me?",
  str_homestory_N19chuanshanjia_90010606_47_dialog_content = "Great idea! Za! Let's take a group photo together!",
  str_homestory_N19chuanshanjia_90010606_48_dialog_content = "Ahahaha... It's so satisfying...",
  str_homestory_N19chuanshanjia_90010606_49_dialog_content = "(I wonder if I should remind them that there are no cameras in Cloud Gardens...)",
  str_homestory_N19chuanshanjia_90010611_1_dialog_content = "She is by the river.",
  str_homestory_N19chuanshanjia_90010612_1_dialog_content = "3 fish... that's enough to keep me fed for a while!",
  str_homestory_N19chuanshanjia_90010613_1_dialog_content = "Remember! Sincerity is the key!",
  str_homestory_N19chuanshanjia_90010614_1_dialog_content = "Go, they can't wait any longer.",
  str_homestory_N19chuanshanjia_90010113_1_dialog_content = "Are there other talking animals?",
  str_homestory_N19chuanshanjia_90010114_1_dialog_content = "Have you found Korgon?",
  str_homestory_N19chuanshanjia_90010115_1_dialog_content = "It's taking so long... Are there really other talking animals?",
  str_homestory_N19chuanshanjia_90010116_1_dialog_content = "Quickly! Sahn will leave if you keep dawdling around."
}
return config
